query:
query TilesDesktopCrashesPerEmployee(
    $timeFrameFilter: DesktopAppTimeframeFilterInput!
  ) {
    overview: desktopAppOverview(timeFrameFilter: $timeFrameFilter) {
      tiles: crashesPerEmployee {
        perAppMetrics {
          appId
          appName
          currentValue
          previousValue
        }
      }
    }
  }
